export interface IndicatorNormRow { group: string; range: string; }
export interface IndicatorFAQ { question: string; answer: string; }
export interface IndicatorData {
  slug: string; name: string; shortName: string; title: string; metaDescription: string;
  category: string; unit: string; referenceRange: { male: string; female: string };
  content: {
    whatIs: string; whyImportant: string; normsTable: IndicatorNormRow[];
    highCauses: string; lowCauses: string; symptoms: string; whatToDo: string;
    relatedIndicators: string[]; faq: IndicatorFAQ[];
  };
}
export function getIndicatorBySlug(slug: string): IndicatorData | undefined { return indicators.find((i) => i.slug === slug); }
export function getIndicatorsByCategory(category: string): IndicatorData[] { return indicators.filter((i) => i.category === category); }
export function getIndicatorSlug(name: string): string | null { return indicatorNameToSlug[name] || null; }
export function getUsedCategories(): string[] { return [...new Set(indicators.map((i) => i.category))]; }
